#include <vector>
#include <cstdlib>
using namespace std;

class Solution {
public:
    long long maxMatrixSum(vector<vector<int>>& matrix) {
        long long sum = 0, minAbs = INT_MAX;
        int negCount = 0;

        for (auto& row : matrix) {
            for (int val : row) {
                sum += abs(val);
                if (val < 0) negCount++;
                minAbs = min(minAbs, (long long)abs(val));
            }
        }

        return negCount % 2 == 0 ? sum : sum - 2 * minAbs;
    }
};
